package run.ikaros.music;
import static org.mockito.ArgumentMatchers.any; import static org.mockito.Mockito.when; import java.time.Instant; import java.util.UUID; import org.junit.jupiter.api.Test; import org.springframework.core.io.buffer.DataBuffer; import org.springframework.core.io.buffer.DefaultDataBufferFactory; import org.springframework.transaction.reactive.TransactionalOperator; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import reactor.test.StepVerifier; import run.ikaros.storage.api.AttachmentAvailabilityStatus; import run.ikaros.storage.api.AttachmentContentService; import run.ikaros.storage.api.AttachmentKind; import run.ikaros.storage.api.AttachmentView; import run.ikaros.storage.api.StorageService;
class PersistentMusicMetadataRecognitionServiceTest {
    @Test void recognizesAndPersistsCandidate() { UUID owner=UUID.randomUUID(),trackId=UUID.randomUUID(),attachmentId=UUID.randomUUID(),candidateId=UUID.randomUUID(); MusicTrackRepository tracks=org.mockito.Mockito.mock(MusicTrackRepository.class); MusicAudioSourceService sources=org.mockito.Mockito.mock(MusicAudioSourceService.class); StorageService storage=org.mockito.Mockito.mock(StorageService.class); AttachmentContentService content=org.mockito.Mockito.mock(AttachmentContentService.class); MusicMetadataCandidateRepository candidates=org.mockito.Mockito.mock(MusicMetadataCandidateRepository.class); TransactionalOperator transaction=org.mockito.Mockito.mock(TransactionalOperator.class); MusicTrackEntity track=new MusicTrackEntity(trackId,owner,UUID.randomUUID(),"fallback",null,null,false,0L); MusicAudioSourceView source=new MusicAudioSourceView(UUID.randomUUID(),trackId,attachmentId,"MP3","MPEG",null,null,null,null,null,false,"AVAILABLE",0); AttachmentView attachment=new AttachmentView(attachmentId,track.resourceId(),"song.mp3",AttachmentKind.ORIGINAL,"sha",64,"audio/mpeg",AttachmentAvailabilityStatus.READY); MusicMetadataCandidateEntity saved=new MusicMetadataCandidateEntity(candidateId,owner,trackId,attachmentId,"Song","Artist",null,null,null,null,null,null,null,"ID3",Instant.now(),Instant.now(),0L); when(tracks.findById(trackId)).thenReturn(Mono.just(track)); when(sources.list(owner,trackId)).thenReturn(Flux.just(source)); when(storage.get(owner,attachmentId)).thenReturn(Mono.just(attachment)); when(content.read(owner,attachmentId)).thenReturn(Flux.just(buffer(id3("TIT2","Song")))); when(candidates.findByOwnerIdAndTrackIdAndAttachmentId(owner,trackId,attachmentId)).thenReturn(Mono.empty()); when(candidates.save(any())).thenReturn(Mono.just(saved)); when(transaction.transactional(any(Mono.class))).thenAnswer(i->i.getArgument(0));
        StepVerifier.create(new PersistentMusicMetadataRecognitionService(tracks,sources,storage,content,candidates,transaction).recognize(owner,trackId)).expectNextMatches(v->"Song".equals(v.title())&&"ID3".equals(v.source())).verifyComplete();
    }
    @Test void rejectsMissingTrack() { MusicTrackRepository tracks=org.mockito.Mockito.mock(MusicTrackRepository.class); TransactionalOperator transaction=org.mockito.Mockito.mock(TransactionalOperator.class); when(tracks.findById(any(UUID.class))).thenReturn(Mono.empty()); when(transaction.transactional(any(Mono.class))).thenAnswer(i->i.getArgument(0)); PersistentMusicMetadataRecognitionService service=new PersistentMusicMetadataRecognitionService(tracks,org.mockito.Mockito.mock(MusicAudioSourceService.class),org.mockito.Mockito.mock(StorageService.class),org.mockito.Mockito.mock(AttachmentContentService.class),org.mockito.Mockito.mock(MusicMetadataCandidateRepository.class),transaction); StepVerifier.create(service.recognize(UUID.randomUUID(),UUID.randomUUID())).expectError(run.ikaros.common.NotFoundException.class).verify(); }
    private DataBuffer buffer(byte[] bytes){DataBuffer b=DefaultDataBufferFactory.sharedInstance.allocateBuffer(bytes.length);b.write(bytes);return b;} private byte[] id3(String id,String text){byte[] value=text.getBytes(java.nio.charset.StandardCharsets.UTF_8);byte[] frame=new byte[11+value.length];System.arraycopy(id.getBytes(java.nio.charset.StandardCharsets.ISO_8859_1),0,frame,0,4);int n=1+value.length;frame[4]=(byte)(n>>24);frame[5]=(byte)(n>>16);frame[6]=(byte)(n>>8);frame[7]=(byte)n;frame[10]=3;System.arraycopy(value,0,frame,11,value.length);byte[] bytes=new byte[10+frame.length];bytes[0]='I';bytes[1]='D';bytes[2]='3';bytes[3]=3;int size=frame.length;bytes[6]=(byte)(size>>21);bytes[7]=(byte)(size>>14);bytes[8]=(byte)(size>>7);bytes[9]=(byte)size;System.arraycopy(frame,0,bytes,10,frame.length);return bytes;}
}
